window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4b01748dc49fa90c"]={"versions": [{"id": "FIG-4b01748dc49fa90c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-basiert). Das Schaubild stellt die Entwurfs- und Konfigurationsaktivität „Configure IO Hardware abstraction“ innerhalb des ECU-Integrationsprozesses der Classic Platform dar. Es visualisiert die beteiligte Rolle, die Eingangs- und Ausgangsartefakte sowie die zugehörigen Kardinalitäten bei der Konfiguration der I/O-Hardware-Abstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Configure IO Hardware abstraction</code>: Zentraler Arbeitsschritt der Konfiguration.\n</li></ul>\n</li><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Kardinalität <code>1</code>, Stereotyp <code>«performs»</code>): Durchführende Rolle für die Aktivität.\n</li></ul>\n</li><li><strong>Artefakte &amp; Schnittstellenbeziehungen</strong>:\n<ul class=\"fig-list\"><li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..*</code>, Stereotyp <code>«input»</code>): Geliefertes BSW-Modulpaket als Eingangsartefakt.\n</li><li><code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> (im Bild als <code>AUTOSAR Standardized ECU...</code> beschriftetes Dokument-Icon, Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>): Standardisierte Parameterdefinitionen als Eingang.\n</li><li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>, Stereotyp <code>«inoutput»</code>): Bestehende ECU-Konfigurationswerte werden eingelesen, durch die Konfiguration der I/O-Hardware-Abstraktion modifiziert/ergänzt und als Ausgabeartefakt fortgeschrieben.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> führt die Aktivität <code>Configure IO Hardware abstraction</code> aus.\n</li><li>Zur Durchführung werden bis zu beliebig viele BSW-Modulpakete (<code>BSW Module Delivered Bundle</code>, <code>0..*</code>) sowie optional die standardisierten ECU-Konfigurationsparameterdefinitionen (<code>0..1</code>) eingelesen.\n</li><li>Die Aktivität liest die vorliegenden <code>ECU Configuration Values</code> ein (<code>«inoutput»</code>), aktualisiert oder ergänzt die Konfiguration für die I/O-Hardware-Abstraktion und schreibt die aktualisierten <code>ECU Configuration Values</code> (<code>1</code>) wieder zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die I/O-Hardware-Abstraktion überbrückt die hardwarenahen Treiber (MCAL) und softwareseitigen Zugriffe.\n</li><li>Die Inout-Kardinalität <code>1</code> an <code>ECU Configuration Values</code> dokumentiert ein inkrementelles Arbeiten auf der zentralen ECU-Konfigurationsdatenbasis (<code>.arxml</code>).\n</li><li>Werkzeuge müssen sicherstellen, dass Referenzen auf unterlagerte I/O-Treiber (z. B. Dio, Adc, Pwm, Port) konsistent in die <code>ECU Configuration Values</code> eingepflegt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6a12901b50841fed", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-basiert). Das Schaubild stellt die Entwurfs- und Konfigurationsaktivität „Configure IO Hardware abstraction“ innerhalb des ECU-Integrationsprozesses der Classic Platform dar. Es visualisiert die beteiligte Rolle, die Eingangs- und Ausgangsartefakte sowie die zugehörigen Kardinalitäten bei der Konfiguration der I/O-Hardware-Abstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Configure IO Hardware abstraction</code>: Zentraler Arbeitsschritt der Konfiguration.\n</li></ul>\n</li><li><strong>Rolle</strong>:\n<ul class=\"fig-list\"><li><code>ECU Integrator</code> (Kardinalität <code>1</code>, Stereotyp <code>«performs»</code>): Durchführende Rolle für die Aktivität.\n</li></ul>\n</li><li><strong>Artefakte &amp; Schnittstellenbeziehungen</strong>:\n<ul class=\"fig-list\"><li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..*</code>, Stereotyp <code>«input»</code>): Geliefertes BSW-Modulpaket als Eingangsartefakt.\n</li><li><code>AUTOSAR Standardized ECU Configuration Parameter Definition</code> (im Bild als <code>AUTOSAR Standardized ECU...</code> beschriftetes Dokument-Icon, Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>): Standardisierte Parameterdefinitionen als Eingang.\n</li><li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>, Stereotyp <code>«inoutput»</code>): Bestehende ECU-Konfigurationswerte werden eingelesen, durch die Konfiguration der I/O-Hardware-Abstraktion modifiziert/ergänzt und als Ausgabeartefakt fortgeschrieben.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ECU Integrator</code> führt die Aktivität <code>Configure IO Hardware abstraction</code> aus.\n</li><li>Zur Durchführung werden bis zu beliebig viele BSW-Modulpakete (<code>BSW Module Delivered Bundle</code>, <code>0..*</code>) sowie optional die standardisierten ECU-Konfigurationsparameterdefinitionen (<code>0..1</code>) eingelesen.\n</li><li>Die Aktivität liest die vorliegenden <code>ECU Configuration Values</code> ein (<code>«inoutput»</code>), aktualisiert oder ergänzt die Konfiguration für die I/O-Hardware-Abstraktion und schreibt die aktualisierten <code>ECU Configuration Values</code> (<code>1</code>) wieder zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die I/O-Hardware-Abstraktion überbrückt die hardwarenahen Treiber (MCAL) und softwareseitigen Zugriffe.\n</li><li>Die Inout-Kardinalität <code>1</code> an <code>ECU Configuration Values</code> dokumentiert ein inkrementelles Arbeiten auf der zentralen ECU-Konfigurationsdatenbasis (<code>.arxml</code>).\n</li><li>Werkzeuge müssen sicherstellen, dass Referenzen auf unterlagerte I/O-Treiber (z. B. Dio, Adc, Pwm, Port) konsistent in die <code>ECU Configuration Values</code> eingepflegt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4b01748dc49fa90c", "to": "FIG-6a12901b50841fed", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
